private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    TreeNode<T> grandParent = parent.getParent();
    TreeNode<T> sibling = parent.getLeft();

    parent.setLeft(sibling.getRight());
    sibling.setRight(parent);

    if (grandParent != null) {
        if (grandParent.getLeft() == parent) {
            grandParent.setLeft(sibling);
        } else {
            grandParent.setRight(sibling);
        }
    }

    sibling.setParent(grandParent);
    parent.setParent(sibling);

    return sibling;
}

