public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Calculate the length of the UTF-8 encoded bytes
    int utf8Length = 0;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            utf8Length += 1;
        } else if (c < 0x800) {
            utf8Length += 2;
        } else if (c < 0x10000) {
            utf8Length += 3;
        } else {
            utf8Length += 4;
        }
    }

    // Allocate a new byte array to hold the UTF-8 encoded bytes
    byte[] bytes = new byte[utf8Length];

    // Encode the string as UTF-8
    int byteIndex = 0;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            bytes[byteIndex++] = (byte) c;
        } else if (c < 0x800) {
            bytes[byteIndex++] = (byte) (0xC0 | (c >> 6));
            bytes[byteIndex++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0x10000) {
            bytes[byteIndex++] = (byte) (0xE0 | (c >> 12));
            bytes[byteIndex++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[byteIndex++] = (byte) (0x80 | (c & 0x3F));
        } else {
            bytes[byteIndex++] = (byte) (0xF0 | (c >> 18));
            bytes[byteIndex++] = (byte) (0x80 | ((c >> 12) & 0x3F));
            bytes[byteIndex++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[byteIndex++] = (byte) (0x80 | (c & 0x3F));
        }
    }

    // Write the UTF-8 encoded bytes to the LinkedBuffer
    lb.writeBytes(bytes);

    return lb;
}

